const w=390; const res=[]; let clicks=0;
const pages=navFor().map(n=>n.k).concat(['lead','event']);
const nav=pg=>{ if(pg==='lead') go('lead',openable()[0]&&openable()[0].id); else if(pg==='event') go('event',EVENTS[0].id); else go(pg); };
for(const pg of pages){ nav(pg); let maxW=document.documentElement.scrollWidth;
  const n=document.querySelectorAll('#pane button').length;
  for(let i=0;i<Math.min(n,40);i++){ const b=[...document.querySelectorAll('#pane button')][i]; if(!b||b.disabled||b.offsetParent===null) continue;
    if(/Sign out|Delete|Remove|Revoke|End access/i.test(b.textContent)) continue;
    try{ b.click(); clicks++; }catch(e){ window.__err++; }
    maxW=Math.max(maxW,document.documentElement.scrollWidth);
    try{ closeDrawer(); }catch(e){}
    if(VIEW!==pg) nav(pg); }
  res.push({page:pg, view:VIEW, maxScrollWidth:maxW}); }
return {seat:WHO, viewport:innerWidth, pagesVisited:res.length, buttonsPressed:clicks,
  overflowing:res.filter(r=>r.maxScrollWidth>w+1).map(r=>r.page+':'+r.maxScrollWidth),
  pages:res.map(r=>r.page+(r.view===r.page?'':'→'+r.view)).join(', '),
  scriptErrors:window.__err, nativeDialogs:window.__dlg};

